import unittest

from hourglass.models import Span
from hourglass.parsing import parse_span
from hourglass.rounding import round_spans


class RoundSpansTests(unittest.TestCase):
    def test_rounds_to_nearest_step(self):
        spans = [parse_span("09:02-17:08")]
        self.assertEqual(
            round_spans(spans, 15), ["09:00-17:15 (8h 15m)"]
        )

    def test_halfway_rounds_up(self):
        spans = [parse_span("09:07-10:22")]
        self.assertEqual(
            round_spans(spans, 15), ["09:00-10:15 (1h 15m)"]
        )

    def test_exact_values_unchanged(self):
        spans = [Span(540, 1020)]
        self.assertEqual(
            round_spans(spans, 30), ["09:00-17:00 (8h 0m)"]
        )

    def test_empty_list(self):
        self.assertEqual(round_spans([], 15), [])

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 120):
            with self.assertRaises(ValueError):
                round_spans([Span(0, 60)], step)
